import Foundation

/// `Documentation/Foundations/TOKEN_COVERAGE.md`: which tokens iOS generates and as what, which it
/// does not and why, which colours needed Display P3, and what tokens.css does not declare.
/// Generated, so it cannot drift.
struct CoverageReport {
    let model: TokenModel
    let stylesheet: Stylesheet
    let provenance: Provenance

    func markdown() throws -> String {
        let package = try provenance.package(Provenance.tokensPackage)
        var lines: [String] = [
            "<!-- GENERATED by qeetrix-gen — do not edit. Run Scripts/generate.sh. -->",
            "",
            "# Token coverage",
            "",
            "Source: `\(package.name)@\(package.version)` (git `\(package.gitHead.prefix(7))`), its DTCG build resolved by",
            "`qeetrix.resolver.json`: colour schemes \(model.source.colorSchemes.map { "`\($0)`" }.joined(separator: ", ")), densities \(model.source.densities.map { "`\($0)`" }.joined(separator: ", ")).",
            "Every value is checked against the package's pre-resolved `light.tokens.json` and `dark.tokens.json` and against `tokens.css`.",
            "",
            "\(model.included.count) tokens are generated as Swift; \(model.excluded.count) are not. The rule is in",
            "[`Tools/QeetrixGen/Sources/QeetrixGenCore/Tokens/Scope.swift`](../../Tools/QeetrixGen/Sources/QeetrixGenCore/Tokens/Scope.swift);",
            "every value is listed in [`token-values.json`](token-values.json).",
            "",
            "## Generated",
            "",
            "| Swift | Tokens | Follows | Paths |",
            "|:--|--:|:--|:--|",
        ]
        for group in TokenGroup.allCases {
            let tokens = model.tokens(group)
            guard !tokens.isEmpty else { continue }
            var prefixes: [String] = []
            for token in tokens {
                let prefix = token.path.count <= 2 ? token.dotted : token.path.prefix(2).joined(separator: ".") + ".*"
                if !prefixes.contains(prefix) { prefixes.append(prefix) }
            }
            let follows = Set(tokens.map(\.variation.rawValue)).sorted().filter { $0 != "none" }
            lines.append(
                "| `\(group.swiftType)` | \(tokens.count) | \(follows.isEmpty ? "—" : follows.joined(separator: ", ")) | \(prefixes.map { "`\($0)`" }.joined(separator: ", ")) |"
            )
        }
        lines.append("")

        lines += ["## Not generated", "", "| Reason | Tokens | Examples |", "|:--|--:|:--|"]
        var reasons: [String] = []
        var byReason: [String: [ExcludedToken]] = [:]
        for token in model.excluded {
            if byReason[token.reason] == nil { reasons.append(token.reason) }
            byReason[token.reason, default: []].append(token)
        }
        for reason in reasons {
            let tokens = byReason[reason]!
            let examples = tokens.prefix(3).map { "`\($0.dotted)`" }.joined(separator: ", ")
            lines.append("| \(reason) | \(tokens.count) | \(examples)\(tokens.count > 3 ? ", …" : "") |")
        }
        lines.append("")

        lines += ["## Colours outside sRGB", ""]
        var wide: [String] = []
        for token in model.tokens(.color) {
            for scheme in model.source.colorSchemes {
                if case let .color(color) = token.value(TokenContext(colorScheme: scheme, density: model.source.densities[0])),
                    color.space == .displayP3
                {
                    wide.append(
                        "| `\(token.dotted)` | \(scheme) | \(color.gamutMapped ? "outside P3 — gamut-mapped (CSS Color 4)" : "inside P3 — drawn in Display P3") |"
                    )
                }
            }
        }
        if wide.isEmpty {
            lines.append("None: every semantic colour converts into sRGB and rounds to the package's own hex value.")
        } else {
            lines +=
                [
                    "These convert outside sRGB. They are drawn in Display P3, which is how Safari paints them on an iPhone.",
                    "",
                    "| Token | Scheme | Handling |",
                    "|:--|:--|:--|",
                ] + wide
        }
        lines.append("")

        let undeclared = stylesheet.undeclared(in: model)
        lines += ["## Not in tokens.css", ""]
        if undeclared.isEmpty {
            lines.append("None: tokens.css declares every generated token.")
        } else {
            lines.append("Generated from the DTCG build, with no `--qx-*` variable to check against:")
            lines.append("")
            lines += undeclared.map { "- `\($0.dotted)`" }
        }
        lines.append("")
        return lines.joined(separator: "\n")
    }
}
